WITH base AS (SELECT *, CEIL(sqft) AS sqft_whole FROM stores WHERE opened_date > '2023-12-01'), valid AS (SELECT *, LENGTH(region) AS region_length FROM base WHERE region IS NOT NULL), not_flagged AS (SELECT s.* FROM valid s WHERE NOT EXISTS (SELECT 1 FROM orders x WHERE x.store_id = s.id AND x.order_date < s.opened_date)), not_flagged_stores AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.store_id = s.id AND c.sale_date <= s.opened_date)) SELECT CASE WHEN sqft >= 14797 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, SIZE(COLLECT_SET(region)) AS num_regions, SORT_ARRAY(COLLECT_SET(region)) AS region_list FROM not_flagged_stores GROUP BY CASE WHEN sqft >= 14797 THEN 'HIGH' ELSE 'LOW' END ORDER BY sqft_tier ASC
